-- ----------------------------
-- Table structure for ai_content_generation
-- ----------------------------
DROP TABLE IF EXISTS `ai_content_generation`;
CREATE TABLE `ai_content_generation`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `landlord_id` bigint NOT NULL COMMENT '房东ID，关联user表',
  `property_id` bigint NULL DEFAULT NULL COMMENT '关联的房源ID，如果已应用到房源则记录，否则为NULL',
  `input_data` json NOT NULL COMMENT '输入的房源信息（JSON格式）：包含户型、面积、价格、位置等',
  `short_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '生成的简短版文案（100-200字）',
  `detail_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '生成的详细版文案（300-500字）',
  `is_applied` tinyint NULL DEFAULT 0 COMMENT '是否已应用到房源：0-未应用，1-已应用',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_landlord_id`(`landlord_id` ASC) USING BTREE COMMENT '房东ID索引，用于查询房东的生成记录',
  INDEX `idx_property_id`(`property_id` ASC) USING BTREE COMMENT '房源ID索引，用于关联查询',
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE COMMENT '创建时间索引，用于按时间排序',
  INDEX `idx_is_applied`(`is_applied` ASC) USING BTREE COMMENT '应用状态索引，用于统计'
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI文案生成记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of ai_content_generation
-- ----------------------------

-- ----------------------------
-- Table structure for ai_qa_history
-- ----------------------------
DROP TABLE IF EXISTS `ai_qa_history`;
CREATE TABLE `ai_qa_history`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint NOT NULL COMMENT '用户ID，关联user表',
  `question` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户提出的问题',
  `answer` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'AI返回的答案',
  `question_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'general' COMMENT '问题类型：buy(买房)/rent(租房)/policy(政策)/layout(户型)/general(通用)',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE COMMENT '用户ID索引，用于查询用户历史记录',
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE COMMENT '创建时间索引，用于按时间排序',
  INDEX `idx_question_type`(`question_type` ASC) USING BTREE COMMENT '问题类型索引，用于统计分析'
) ENGINE = InnoDB AUTO_INCREMENT = 50 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI问答历史记录表' ROW_FORMAT = DYNAMIC;

