-- ----------------------------
-- Table structure for ai_recommendation_log
-- ----------------------------
DROP TABLE IF EXISTS `ai_recommendation_log`;
CREATE TABLE `ai_recommendation_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint NOT NULL COMMENT '用户ID，关联user表',
  `property_id` bigint NOT NULL COMMENT '推荐的房源ID，关联property表',
  `recommend_score` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '推荐分数（0-100），分数越高表示越匹配用户偏好',
  `recommend_reason` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '推荐理由：如\"基于您的浏览历史\"、\"相似房源推荐\"等',
  `is_clicked` tinyint NULL DEFAULT 0 COMMENT '是否点击：0-未点击，1-已点击',
  `click_time` datetime NULL DEFAULT NULL COMMENT '点击时间，用户点击推荐房源时记录',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '推荐时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE COMMENT '用户ID索引，用于查询用户的推荐记录',
  INDEX `idx_property_id`(`property_id` ASC) USING BTREE COMMENT '房源ID索引，用于统计房源被推荐次数',
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE COMMENT '创建时间索引，用于按时间排序',
  INDEX `idx_is_clicked`(`is_clicked` ASC) USING BTREE COMMENT '点击状态索引，用于统计点击率',
  INDEX `idx_recommend_score`(`recommend_score` ASC) USING BTREE COMMENT '推荐分数索引，用于排序'
) ENGINE = InnoDB AUTO_INCREMENT = 4338 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI推荐日志表' ROW_FORMAT = DYNAMIC;

