-- ----------------------------
-- Table structure for payment_record
-- ----------------------------
DROP TABLE IF EXISTS `payment_record`;
CREATE TABLE `payment_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'Primary key',
  `appointment_id` bigint NOT NULL COMMENT 'Appointment ID',
  `contract_id` bigint NULL DEFAULT NULL COMMENT 'Contract ID',
  `payment_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Payment type: deposit, rent, down_payment, balance, service_fee',
  `amount` decimal(12, 2) NOT NULL COMMENT 'Amount',
  `payment_method` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Payment method: wechat, alipay, bank_transfer',
  `payment_status` tinyint NOT NULL DEFAULT 0 COMMENT 'Payment status: 0-pending, 1-paid, 2-refunded',
  `payer_id` bigint NOT NULL COMMENT 'Payer ID',
  `payee_id` bigint NOT NULL COMMENT 'Payee ID',
  `payment_time` datetime NULL DEFAULT NULL COMMENT 'Payment time',
  `transaction_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Transaction number',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'Remark',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Create time',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_appointment_id`(`appointment_id` ASC) USING BTREE,
  INDEX `idx_contract_id`(`contract_id` ASC) USING BTREE,
  INDEX `idx_payment_status`(`payment_status` ASC) USING BTREE,
  INDEX `idx_payer_id`(`payer_id` ASC) USING BTREE,
  INDEX `fk_payment_payee`(`payee_id` ASC) USING BTREE,
  CONSTRAINT `fk_payment_appointment` FOREIGN KEY (`appointment_id`) REFERENCES `appointment` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_payment_contract` FOREIGN KEY (`contract_id`) REFERENCES `contract` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `fk_payment_payee` FOREIGN KEY (`payee_id`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_payment_payer` FOREIGN KEY (`payer_id`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'Payment record table' ROW_FORMAT = DYNAMIC;

