-- ----------------------------
-- Table structure for property
-- ----------------------------
DROP TABLE IF EXISTS `property`;
CREATE TABLE `property`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '房源ID，主键',
  `landlord_id` bigint NOT NULL COMMENT '房东ID',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '房源标题',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '房源描述',
  `price` decimal(15, 2) NOT NULL COMMENT '价格（元/月或总价）',
  `price_type` tinyint NOT NULL DEFAULT 0 COMMENT '价格类型：0-月租，1-总价',
  `area` decimal(10, 2) NOT NULL COMMENT '面积（平方米）',
  `bedrooms` int NULL DEFAULT 0 COMMENT '卧室数量',
  `bathrooms` int NULL DEFAULT 0 COMMENT '卫生间数量',
  `orientation` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '朝向',
  `floor` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '楼层',
  `address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '详细地址',
  `city` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '城市',
  `district` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '区域/区县',
  `property_type` tinyint NOT NULL DEFAULT 0 COMMENT '房源类型：0-住宅，1-公寓，2-别墅，3-商铺',
  `transaction_type` tinyint NOT NULL DEFAULT 0 COMMENT '交易类型：0-出租，1-出售',
  `images` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '房源图片URL，多个用逗号分隔',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0-待审核，1-审核通过，2-审核驳回，3-已上架，4-已下架',
  `view_count` int NOT NULL DEFAULT 0 COMMENT '浏览次数',
  `reject_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_landlord_id`(`landlord_id` ASC) USING BTREE,
  INDEX `idx_city`(`city` ASC) USING BTREE,
  INDEX `idx_district`(`district` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_price`(`price` ASC) USING BTREE,
  CONSTRAINT `fk_property_landlord` FOREIGN KEY (`landlord_id`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 6569 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '房源表' ROW_FORMAT = DYNAMIC;

