-- ----------------------------
-- Table structure for transaction_payment
-- ----------------------------
DROP TABLE IF EXISTS `transaction_payment`;
CREATE TABLE `transaction_payment`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '支付记录ID',
  `appointment_id` bigint NOT NULL COMMENT '预约ID',
  `stage_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '阶段代码',
  `payment_type` tinyint NOT NULL COMMENT '支付类型:1-定金,2-首付,3-尾款,4-租金,5-押金',
  `amount` decimal(10, 2) NOT NULL COMMENT '支付金额',
  `payment_method` tinyint NOT NULL COMMENT '支付方式:1-微信,2-支付宝,3-银行卡,4-现金',
  `payment_status` tinyint NOT NULL DEFAULT 0 COMMENT '支付状态:0-待支付,1-已支付,2-已退款',
  `payer_id` bigint NOT NULL COMMENT '支付人ID',
  `payer_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '支付人姓名',
  `transaction_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '交易流水号',
  `payment_time` datetime NULL DEFAULT NULL COMMENT '支付时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_appointment_id`(`appointment_id` ASC) USING BTREE,
  INDEX `idx_transaction_no`(`transaction_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '流程支付记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of transaction_payment
-- ----------------------------

-- ----------------------------
-- Table structure for transaction_process_log
-- ----------------------------
DROP TABLE IF EXISTS `transaction_process_log`;
CREATE TABLE `transaction_process_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'Primary key',
  `appointment_id` bigint NOT NULL COMMENT 'Appointment ID',
  `stage_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Stage code',
  `stage_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Stage name',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT 'Status: 0-in progress, 1-completed, 2-rejected, 3-cancelled',
  `operator_id` bigint NULL DEFAULT NULL COMMENT 'Operator ID',
  `operator_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Operator name',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'Remark',
  `attachment_urls` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'Attachment URLs (JSON array)',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Create time',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Update time',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_appointment_id`(`appointment_id` ASC) USING BTREE,
  INDEX `idx_stage_code`(`stage_code` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  CONSTRAINT `fk_process_log_appointment` FOREIGN KEY (`appointment_id`) REFERENCES `appointment` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 62 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'Transaction process log table' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of transaction_process_log
-- ----------------------------

-- ----------------------------
-- Table structure for transaction_statistics
-- ----------------------------
DROP TABLE IF EXISTS `transaction_statistics`;
CREATE TABLE `transaction_statistics`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '统计ID',
  `stat_date` date NOT NULL COMMENT '统计日期',
  `total_count` int NOT NULL DEFAULT 0 COMMENT '总流程数',
  `completed_count` int NOT NULL DEFAULT 0 COMMENT '已完成数',
  `cancelled_count` int NOT NULL DEFAULT 0 COMMENT '已取消数',
  `in_progress_count` int NOT NULL DEFAULT 0 COMMENT '进行中数',
  `avg_duration_days` decimal(10, 2) NULL DEFAULT NULL COMMENT '平均完成天数',
  `total_amount` decimal(15, 2) NULL DEFAULT NULL COMMENT '总交易金额',
  `transaction_type` tinyint NOT NULL COMMENT '交易类型:0-租房,1-买房',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_date_type`(`stat_date` ASC, `transaction_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '流程统计表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of transaction_statistics
