-- ----------------------------
-- Table structure for user
-- ----------------------------
DROP TABLE IF EXISTS `user`;
CREATE TABLE `user`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '用户ID，主键',
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户名，唯一',
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '密码（BCrypt加密）',
  `real_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '真实姓名',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '手机号码',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '电子邮箱',
  `role` tinyint NOT NULL DEFAULT 0 COMMENT '用户角色：0-普通用户，1-房东，2-管理员',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '用户状态：0-禁用，1-正常',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '头像URL',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `last_login_time` datetime NULL DEFAULT NULL COMMENT '最后登录时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注信息',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_username`(`username` ASC) USING BTREE,
  UNIQUE INDEX `uk_phone`(`phone` ASC) USING BTREE,
  INDEX `idx_role`(`role` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 58 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of user
-- ----------------------------

-- ----------------------------
-- Table structure for user_behavior_log
-- ----------------------------
DROP TABLE IF EXISTS `user_behavior_log`;
CREATE TABLE `user_behavior_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint NOT NULL COMMENT '用户ID，关联user表',
  `property_id` bigint NOT NULL COMMENT '房源ID，关联property表',
  `behavior_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '行为类型：view(浏览)/favorite(收藏)/appointment(预约)/unfavorite(取消收藏)',
  `behavior_detail` json NULL COMMENT '行为详情（JSON格式）：如浏览时长、预约时间等',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '行为发生时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE COMMENT '用户ID索引，用于查询用户行为历史',
  INDEX `idx_property_id`(`property_id` ASC) USING BTREE COMMENT '房源ID索引，用于统计房源热度',
  INDEX `idx_behavior_type`(`behavior_type` ASC) USING BTREE COMMENT '行为类型索引，用于分类统计',
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE COMMENT '创建时间索引，用于按时间排序',
  INDEX `idx_user_property`(`user_id` ASC, `property_id` ASC) USING BTREE COMMENT '用户-房源复合索引，用于去重和关联查询'
) ENGINE = InnoDB AUTO_INCREMENT = 174 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户行为日志表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of user_behavior_log
-- ----------------------------

-- ----------------------------
-- View structure for message_conversation_list
-- ----------------------------
DROP VIEW IF EXISTS `message_conversation_list`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `message_conversation_list` AS select `message`.`conversation_id` AS `conversation_id`,`message`.`property_id` AS `property_id`,`message`.`user_id` AS `user_id`,`message`.`landlord_id` AS `landlord_id`,max(`message`.`id`) AS `last_message_id`,max(`message`.`last_message_time`) AS `last_message_time`,count(0) AS `message_count`,sum((case when ((`message`.`is_read` = 0) and (`message`.`sender_role` = 0)) then 1 else 0 end)) AS `landlord_unread_count`,sum((case when ((`message`.`is_read` = 0) and (`message`.`sender_role` = 1)) then 1 else 0 end)) AS `user_unread_count` from `message` group by `message`.`conversation_id`,`message`.`property_id`,`message`.`user_id`,`message`.`landlord_id`;

-- ----------------------------
-- Procedure structure for generate_all_data
-- ----------------------------
DROP PROCEDURE IF EXISTS `generate_all_data`;
delimiter ;;
CREATE PROCEDURE `generate_all_data`()
BEGIN
    SELECT '========================================' AS message;
    SELECT '开始生成所有测试数据...' AS message;
    SELECT '========================================' AS message;
    
    -- 生成200个房源
    CALL generate_properties(200);
    
    -- 生成500个收藏
    CALL generate_favorites(500);
    
    -- 生成300个预约
    CALL generate_appointments(300);
    
    -- 生成200个留言
    CALL generate_messages(200);
    
    SELECT '========================================' AS message;
    SELECT '所有数据生成完成！' AS message;
    SELECT '========================================' AS message;
    
    -- 显示统计信息
    SELECT 
        (SELECT COUNT(*) FROM user) AS 用户总数,
        (SELECT COUNT(*) FROM property) AS 房源总数,
        (SELECT COUNT(*) FROM favorite) AS 收藏总数,
        (SELECT COUNT(*) FROM appointment) AS 预约总数,
        (SELECT COUNT(*) FROM message) AS 留言总数;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for generate_appointments
-- ----------------------------
DROP PROCEDURE IF EXISTS `generate_appointments`;
delimiter ;;
CREATE PROCEDURE `generate_appointments`(IN num_appointments INT)
BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE user_id_val BIGINT;
    DECLARE property_id_val BIGINT;
    DECLARE landlord_id_val BIGINT;
    DECLARE appt_time DATETIME;
    DECLARE appt_status INT;
    DECLARE max_property_id BIGINT;
    
    SELECT '开始生成预约数据...' AS message;
    SELECT MAX(id) INTO max_property_id FROM property;
    
    appointment_loop: WHILE i <= num_appointments DO
        -- 随机选择用户（ID 4-34，普通用户）
        SET user_id_val = FLOOR(4 + RAND() * 31);
        
        -- 随机选择房源
        SET property_id_val = FLOOR(1 + RAND() * max_property_id);
        
        -- 获取房东ID
        SET landlord_id_val = NULL;
        SELECT landlord_id INTO landlord_id_val 
        FROM property 
        WHERE id = property_id_val 
        LIMIT 1;
        
        -- 如果没找到房源，跳过
        IF landlord_id_val IS NULL THEN
            SET i = i + 1;
            ITERATE appointment_loop;
        END IF;
        
        -- 随机预约时间（过去30天到未来30天）
        SET appt_time = DATE_ADD(NOW(), INTERVAL FLOOR(-30 + RAND() * 60) DAY);
        
        -- 根据时间设置状态
        IF appt_time < NOW() THEN
            SET appt_status = FLOOR(2 + RAND() * 2);  -- 已完成或已取消
        ELSE
            SET appt_status = FLOOR(RAND() * 2);  -- 待确认或已确认
        END IF;
        
        -- 插入预约
            user_id, property_id, landlord_id, appointment_time, 
            contact_phone, remark, status
        ) VALUES (
            user_id_val,
            property_id_val,
            landlord_id_val,
            appt_time,
            CONCAT('137', LPAD(FLOOR(RAND() * 100000000), 8, '0')),
            ELT(FLOOR(1 + RAND() * 5), 
                '想周末看房，方便吗？', 
                '下午有空，可以预约看房吗？', 
                '对这个房源很感兴趣，想尽快看房。', 
                '请问这个时间可以吗？', 
                NULL),
            appt_status
        );
        
        SET i = i + 1;
        
        -- 每100条提交一次
        IF i % 100 = 0 THEN
            COMMIT;
            SELECT CONCAT('已生成 ', i, ' 条预约数据...') AS progress;
        END IF;
    END WHILE;
    
    COMMIT;
    SELECT CONCAT('预约数据生成完成！共生成 ', num_appointments, ' 条记录。') AS message;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for generate_favorites
-- ----------------------------
DROP PROCEDURE IF EXISTS `generate_favorites`;
delimiter ;;
CREATE PROCEDURE `generate_favorites`(IN num_favorites INT)
BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE user_id_val BIGINT;
    DECLARE property_id_val BIGINT;
    DECLARE max_property_id BIGINT;
    DECLARE CONTINUE HANDLER FOR 1062 SET i = i;  -- 忽略重复键错误
    
    SELECT '开始生成收藏数据...' AS message;
    SELECT MAX(id) INTO max_property_id FROM property;
    
    WHILE i <= num_favorites DO
        -- 随机选择用户（ID 4-34，普通用户）
        SET user_id_val = FLOOR(4 + RAND() * 31);
        
        -- 随机选择房源
        SET property_id_val = FLOOR(1 + RAND() * max_property_id);
        
        -- 插入收藏（忽略重复）
        VALUES (user_id_val, property_id_val);
        
        SET i = i + 1;
        
        -- 每100条提交一次
        IF i % 100 = 0 THEN
            COMMIT;
            SELECT CONCAT('已生成 ', i, ' 条收藏数据...') AS progress;
        END IF;
    END WHILE;
    
    COMMIT;
    SELECT CONCAT('收藏数据生成完成！共生成 ', (SELECT COUNT(*) FROM favorite), ' 条记录。') AS message;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for generate_messages
-- ----------------------------
DROP PROCEDURE IF EXISTS `generate_messages`;
delimiter ;;
CREATE PROCEDURE `generate_messages`(IN num_messages INT)
BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE user_id_val BIGINT;
    DECLARE property_id_val BIGINT;
    DECLARE landlord_id_val BIGINT;
    DECLARE is_read_val INT;
    DECLARE max_property_id BIGINT;
    
    SELECT '开始生成留言数据...' AS message;
    SELECT MAX(id) INTO max_property_id FROM property;
    
    message_loop: WHILE i <= num_messages DO
        -- 随机选择用户（ID 4-34，普通用户）
        SET user_id_val = FLOOR(4 + RAND() * 31);
        
        -- 随机选择房源
        SET property_id_val = FLOOR(1 + RAND() * max_property_id);
        
        -- 获取房东ID
        SET landlord_id_val = NULL;
        SELECT landlord_id INTO landlord_id_val 
        FROM property 
        WHERE id = property_id_val 
        LIMIT 1;
        
        -- 如果没找到房源，跳过
        IF landlord_id_val IS NULL THEN
            SET i = i + 1;
            ITERATE message_loop;
        END IF;
        
        -- 随机是否已读
        SET is_read_val = FLOOR(RAND() * 2);
        
        -- 插入留言
            user_id, landlord_id, property_id, content, reply, is_read
        ) VALUES (
            user_id_val,
            landlord_id_val,
            property_id_val,
            ELT(FLOOR(1 + RAND() * 10),
                '请问这个房源还在吗？',
                '可以议价吗？',
                '什么时候可以看房？',
                '房子装修是什么时候的？',
                '周边配套怎么样？',
                '有停车位吗？',
                '可以养宠物吗？',
                '物业费多少？',
                '这个房子采光怎么样？',
                '附近有地铁站吗？'),
            IF(is_read_val = 1, 
               ELT(FLOOR(1 + RAND() * 5),
                   '房源还在，欢迎预约看房。',
                   '可以小刀，具体面谈。',
                   '随时可以看房，提前预约即可。',
                   '去年刚装修的，全新家具家电。',
                   '周边配套齐全，生活便利。'),
               NULL),
            is_read_val
        );
        
        SET i = i + 1;
        
        -- 每100条提交一次
        IF i % 100 = 0 THEN
            COMMIT;
            SELECT CONCAT('已生成 ', i, ' 条留言数据...') AS progress;
        END IF;
    END WHILE;
    
    COMMIT;
    SELECT CONCAT('留言数据生成完成！共生成 ', num_messages, ' 条记录。') AS message;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for generate_properties
-- ----------------------------
DROP PROCEDURE IF EXISTS `generate_properties`;
delimiter ;;
CREATE PROCEDURE `generate_properties`(IN num_properties INT)
BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE landlord INT;
    DECLARE city_name VARCHAR(50);
    DECLARE district_name VARCHAR(50);
    DECLARE prop_type INT;
    DECLARE trans_type INT;
    DECLARE price_val DECIMAL(15,2);
    DECLARE area_val DECIMAL(10,2);
    DECLARE bedrooms_val INT;
    DECLARE bathrooms_val INT;
    
    SELECT '开始生成房源数据...' AS message;
    
    WHILE i <= num_properties DO
        -- 随机选择房东（ID 2-22）
        SET landlord = FLOOR(2 + RAND() * 21);
        
        -- 随机选择城市和区域
        CASE FLOOR(RAND() * 8)
            WHEN 0 THEN 
                SET city_name = '北京';
                SET district_name = ELT(FLOOR(1 + RAND() * 8), '朝阳区', '海淀区', '东城区', '西城区', '丰台区', '石景山区', '通州区', '昌平区');
            WHEN 1 THEN 
                SET city_name = '上海';
                SET district_name = ELT(FLOOR(1 + RAND() * 8), '浦东新区', '黄浦区', '徐汇区', '长宁区', '静安区', '普陀区', '虹口区', '杨浦区');
            WHEN 2 THEN 
                SET city_name = '广州';
                SET district_name = ELT(FLOOR(1 + RAND() * 8), '天河区', '越秀区', '海珠区', '荔湾区', '白云区', '黄埔区', '番禺区', '花都区');
            WHEN 3 THEN 
                SET city_name = '深圳';
                SET district_name = ELT(FLOOR(1 + RAND() * 8), '福田区', '罗湖区', '南山区', '宝安区', '龙岗区', '盐田区', '龙华区', '坪山区');
            WHEN 4 THEN 
                SET city_name = '杭州';
                SET district_name = ELT(FLOOR(1 + RAND() * 8), '西湖区', '上城区', '下城区', '江干区', '拱墅区', '滨江区', '萧山区', '余杭区');
            WHEN 5 THEN 
                SET city_name = '成都';
                SET district_name = ELT(FLOOR(1 + RAND() * 8), '锦江区', '青羊区', '金牛区', '武侯区', '成华区', '龙泉驿区', '青白江区', '新都区');
            WHEN 6 THEN 
                SET city_name = '重庆';
                SET district_name = ELT(FLOOR(1 + RAND() * 8), '渝中区', '江北区', '南岸区', '九龙坡区', '沙坪坝区', '大渡口区', '渝北区', '巴南区');
            ELSE 
                SET city_name = '武汉';
                SET district_name = ELT(FLOOR(1 + RAND() * 7), '江岸区', '江汉区', '硚口区', '汉阳区', '武昌区', '青山区', '洪山区');
        END CASE;
        
        -- 随机房源类型和交易类型
        SET prop_type = FLOOR(RAND() * 4);  -- 0-3: 住宅、公寓、别墅、商铺
        SET trans_type = FLOOR(RAND() * 2);  -- 0-1: 出租、出售
        
        -- 根据房源类型设置面积和户型
        CASE prop_type
            WHEN 0 THEN  -- 住宅
                SET area_val = 60 + FLOOR(RAND() * 100);  -- 60-160㎡
                SET bedrooms_val = FLOOR(1 + RAND() * 4);  -- 1-4室
                SET bathrooms_val = FLOOR(1 + RAND() * 3);  -- 1-3卫
            WHEN 1 THEN  -- 公寓
                SET area_val = 40 + FLOOR(RAND() * 60);  -- 40-100㎡
                SET bedrooms_val = FLOOR(1 + RAND() * 3);  -- 1-3室
                SET bathrooms_val = FLOOR(1 + RAND() * 2);  -- 1-2卫
            WHEN 2 THEN  -- 别墅
                SET area_val = 200 + FLOOR(RAND() * 300);  -- 200-500㎡
                SET bedrooms_val = FLOOR(3 + RAND() * 4);  -- 3-6室
                SET bathrooms_val = FLOOR(2 + RAND() * 4);  -- 2-5卫
            ELSE  -- 商铺
                SET area_val = 50 + FLOOR(RAND() * 200);  -- 50-250㎡
                SET bedrooms_val = 0;
                SET bathrooms_val = FLOOR(1 + RAND() * 2);  -- 1-2卫
        END CASE;
        
        -- 根据交易类型和房源类型设置价格
        IF trans_type = 0 THEN  -- 出租
            CASE prop_type
                WHEN 0 THEN SET price_val = 2000 + FLOOR(RAND() * 6000);  -- 住宅租金 2000-8000
                WHEN 1 THEN SET price_val = 1500 + FLOOR(RAND() * 4500);  -- 公寓租金 1500-6000
                WHEN 2 THEN SET price_val = 8000 + FLOOR(RAND() * 12000);  -- 别墅租金 8000-20000
                ELSE SET price_val = 5000 + FLOOR(RAND() * 15000);  -- 商铺租金 5000-20000
            END CASE;
        ELSE  -- 出售
            CASE prop_type
                WHEN 0 THEN SET price_val = 2000000 + FLOOR(RAND() * 8000000);  -- 住宅售价 200万-1000万
                WHEN 1 THEN SET price_val = 1500000 + FLOOR(RAND() * 3500000);  -- 公寓售价 150万-500万
                WHEN 2 THEN SET price_val = 8000000 + FLOOR(RAND() * 22000000);  -- 别墅售价 800万-3000万
                ELSE SET price_val = 3000000 + FLOOR(RAND() * 7000000);  -- 商铺售价 300万-1000万
            END CASE;
        END IF;
        
        -- 插入房源
            landlord_id, title, description, price, price_type, area, 
            bedrooms, bathrooms, orientation, floor, address, city, district, 
            property_type, transaction_type, images, status, view_count
        ) VALUES (
            landlord,
            CONCAT(city_name, district_name, 
                   ELT(prop_type + 1, '精装住宅', '温馨公寓', '豪华别墅', '临街商铺'),
                   IF(trans_type = 0, '出租', '出售')),
            CONCAT('优质房源，位置优越，交通便利，配套齐全。',
                   IF(trans_type = 0, '拎包入住，家电齐全。', '产权清晰，随时看房。'),
                   '房源编号：P', LPAD(i, 6, '0')),
            price_val,
            trans_type,
            area_val,
            bedrooms_val,
            bathrooms_val,
            ELT(FLOOR(1 + RAND() * 5), '朝南', '朝北', '朝东', '朝西', '南北通透'),
            CONCAT(FLOOR(1 + RAND() * 30), '/', FLOOR(20 + RAND() * 30)),
            CONCAT(city_name, district_name, 
                   ELT(FLOOR(1 + RAND() * 10), '建国路', '中山路', '人民路', '解放路', '和平路', '胜利路', '光明路', '幸福路', '文化路', '科技路'),
                   FLOOR(1 + RAND() * 999), '号'),
            city_name,
            district_name,
            prop_type,
            trans_type,
            'https://placehold.co/400x300/e5e7eb/0a0a0a?text=房源图片,https://placehold.co/400x300/d1d5db/0a0a0a?text=房源图片2,https://placehold.co/400x300/c7cad1/0a0a0a?text=房源图片3',
            3,  -- 已上架
            FLOOR(RAND() * 1000)  -- 浏览次数 0-999
        );
        
        SET i = i + 1;
        
        -- 每100条提交一次
        IF i % 100 = 0 THEN
            COMMIT;
            SELECT CONCAT('已生成 ', i, ' 条房源数据...') AS progress;
        END IF;
    END WHILE;
    
    COMMIT;
    SELECT CONCAT('房源数据生成完成！共生成 ', num_properties, ' 条记录。') AS message;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for generate_realistic_data
-- ----------------------------
DROP PROCEDURE IF EXISTS `generate_realistic_data`;
delimiter ;;
CREATE PROCEDURE `generate_realistic_data`()
BEGIN
    SELECT '========================================' AS '';
    SELECT '开始生成真实感测试数据...' AS '';
    SELECT '========================================' AS '';
    
    -- 生成200个真实感房源
    CALL generate_realistic_properties(200);
    
    -- 生成收藏、预约、留言（使用原有的存储过程）
    CALL generate_favorites(500);
    CALL generate_appointments(300);
    CALL generate_messages(200);
    
    SELECT '========================================' AS '';
    SELECT '✅ 所有真实感数据生成完成！' AS '';
    SELECT '========================================' AS '';
    
    -- 显示统计信息
    SELECT 
        (SELECT COUNT(*) FROM user) AS 用户总数,
        (SELECT COUNT(*) FROM property) AS 房源总数,
        (SELECT COUNT(*) FROM favorite) AS 收藏总数,
        (SELECT COUNT(*) FROM appointment) AS 预约总数,
        (SELECT COUNT(*) FROM message) AS 留言总数;
        
    -- 显示城市分布
    SELECT '房源城市分布：' AS '';
    SELECT 
        city AS 城市,
        COUNT(*) AS 数量,
        CONCAT(ROUND(COUNT(*) / (SELECT COUNT(*) FROM property) * 100, 1), '%') AS 占比
    FROM property
    GROUP BY city
    ORDER BY COUNT(*) DESC;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for generate_realistic_properties
-- ----------------------------
DROP PROCEDURE IF EXISTS `generate_realistic_properties`;
delimiter ;;
CREATE PROCEDURE `generate_realistic_properties`(IN num_properties INT)
BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE landlord INT;
    DECLARE city_name VARCHAR(50);
    DECLARE district_name VARCHAR(50);
    DECLARE community_name VARCHAR(100);
    DECLARE street_name VARCHAR(50);
    DECLARE prop_type INT;
    DECLARE trans_type INT;
    DECLARE price_val DECIMAL(15,2);
    DECLARE area_val DECIMAL(10,2);
    DECLARE bedrooms_val INT;
    DECLARE bathrooms_val INT;
    DECLARE floor_val VARCHAR(50);
    DECLARE orientation_val VARCHAR(20);
    DECLARE title_val VARCHAR(200);
    DECLARE desc_val TEXT;
    DECLARE images_val TEXT;
    
    SELECT '开始生成真实感房源数据...' AS message;
    
    property_loop: WHILE i <= num_properties DO
        -- 随机选择房东（ID 2-22）
        SET landlord = FLOOR(2 + RAND() * 21);
        
        -- 随机选择城市、区域和小区
        CASE FLOOR(RAND() * 8)
            WHEN 0 THEN 
                SET city_name = '北京';
                SET district_name = ELT(FLOOR(1 + RAND() * 8), '朝阳区', '海淀区', '东城区', '西城区', '丰台区', '石景山区', '通州区', '昌平区');
                SET community_name = ELT(FLOOR(1 + RAND() * 20), 
                    '万科星园', '保利中央公园', '绿地香颂', '华润橡树湾', '龙湖天街',
                    '融创壹号院', '金茂府', '泰禾金尊府', '远洋天著', '首开国风美唐',
                    '中海寰宇天下', '招商雍景湾', '世茂工三', '华侨城', '富力城',
                    '万柳书院', '西山壹号院', '钓鱼台七号院', '泛海国际', '北京壹号院');
                SET street_name = ELT(FLOOR(1 + RAND() * 10), 
                    '建国路', '中关村大街', '王府井大街', '金融街', '三里屯路',
                    '望京街', '亚运村', '国贸', 'CBD', '五道口');
                    
            WHEN 1 THEN 
                SET city_name = '上海';
                SET district_name = ELT(FLOOR(1 + RAND() * 8), '浦东新区', '黄浦区', '徐汇区', '长宁区', '静安区', '普陀区', '虹口区', '杨浦区');
                SET community_name = ELT(FLOOR(1 + RAND() * 20),
                    '汤臣一品', '绿城黄浦湾', '仁恒滨江园', '世茂滨江花园', '东方巴黎',
                    '中粮海景壹号', '万科翡翠滨江', '绿地海珀旭晖', '保利茉莉公馆', '融创滨江壹号院',
                    '华润外滩九里', '招商雍华府', '龙湖天璞', '金地天逸', '中海建国里',
                    '绿城玫瑰园', '古北壹号', '九间堂', '佘山三号', '檀宫');
                SET street_name = ELT(FLOOR(1 + RAND() * 10),
                    '南京路', '淮海路', '陆家嘴环路', '徐家汇路', '静安寺',
                    '人民广场', '外滩', '新天地', '田子坊', '衡山路');
                    
            WHEN 2 THEN 
                SET city_name = '广州';
                SET district_name = ELT(FLOOR(1 + RAND() * 8), '天河区', '越秀区', '海珠区', '荔湾区', '白云区', '黄埔区', '番禺区', '花都区');
                SET community_name = ELT(FLOOR(1 + RAND() * 20),
                    '珠江新城', '保利中环广场', '富力盈凯广场', '合景天峻', '越秀星汇云城',
                    '万科欧泊', '中海花城湾', '保利天悦', '龙湖天奕', '时代廊桥',
                    '雅居乐花园', '碧桂园凤凰城', '星河湾', '祈福新邨', '华南碧桂园',
                    '金地荔湖城', '万科城', '保利香槟国际', '富力桃园', '合生帝景山庄');
                SET street_name = ELT(FLOOR(1 + RAND() * 10),
                    '天河路', '中山路', '北京路', '上下九', '珠江新城',
                    '体育西路', '五羊新城', '海珠广场', '琶洲', '番禺广场');
                    
            WHEN 3 THEN 
                SET city_name = '深圳';
                SET district_name = ELT(FLOOR(1 + RAND() * 8), '福田区', '罗湖区', '南山区', '宝安区', '龙岗区', '盐田区', '龙华区', '坪山区');
                SET community_name = ELT(FLOOR(1 + RAND() * 20),
                    '华侨城', '深圳湾壹号', '万科星城', '招商海月', '中海阳光玫瑰园',
                    '深业上城', '卓越维港', '京基御景华城', '华润城', '前海时代',
                    '深圳湾1号', '红树西岸', '半岛城邦', '蛇口花园城', '海上世界',
                    '科技园', '后海', '车公庙', '华强北', '东门');
                SET street_name = ELT(FLOOR(1 + RAND() * 10),
                    '深南大道', '滨海大道', '科技园', '华强北', '东门',
                    '蛇口', '南山', '福田中心', '罗湖口岸', '前海');
                    
            WHEN 4 THEN 
                SET city_name = '杭州';
                SET district_name = ELT(FLOOR(1 + RAND() * 8), '西湖区', '上城区', '下城区', '江干区', '拱墅区', '滨江区', '萧山区', '余杭区');
                SET community_name = ELT(FLOOR(1 + RAND() * 20),
                    '绿城西溪诚园', '万科西庐', '融创河滨之城', '保利东湾', '龙湖滟澜山',
                    '绿城蓝色钱江', '万科公园大道', '滨江金色黎明', '九龙仓碧玺', '绿城桂花城',
                    '西溪蝶园', '西溪诚园', '申花板块', '未来科技城', '钱江新城',
                    '奥体板块', '滨江新城', '城西银泰城', '西湖文化广场', '武林广场');
                SET street_name = ELT(FLOOR(1 + RAND() * 10),
                    '文三路', '教工路', '西湖大道', '延安路', '庆春路',
                    '钱江路', '滨江路', '萧山路', '余杭路', '拱墅路');
                    
            WHEN 5 THEN 
                SET city_name = '成都';
                SET district_name = ELT(FLOOR(1 + RAND() * 8), '锦江区', '青羊区', '金牛区', '武侯区', '成华区', '龙泉驿区', '青白江区', '新都区');
                SET community_name = ELT(FLOOR(1 + RAND() * 20),
                    '麓山国际', '保利中心', '仁恒滨河湾', '万科金域蓝湾', '龙湖三千庭',
                    '中海国际', '华润二十四城', '绿地中心', '银泰中心', '万象城',
                    '天府新区', '高新区', '金融城', '环球中心', '世纪城',
                    '南门', '春熙路', '太古里', '宽窄巷子', '锦里');
                SET street_name = ELT(FLOOR(1 + RAND() * 10),
                    '人民南路', '天府大道', '红星路', '春熙路', '盐市口',
                    '骡马市', '玉林路', '科华路', '一环路', '二环路');
                    
            WHEN 6 THEN 
                SET city_name = '重庆';
                SET district_name = ELT(FLOOR(1 + RAND() * 8), '渝中区', '江北区', '南岸区', '九龙坡区', '沙坪坝区', '大渡口区', '渝北区', '巴南区');
                SET community_name = ELT(FLOOR(1 + RAND() * 20),
                    '龙湖西苑', '保利香槟国际', '融创欧麓花园城', '万科锦程', '金科廊桥水岸',
                    '协信星光时代', '华宇城', '约克郡', '中央公园', '照母山',
                    '解放碑', '观音桥', '南坪', '杨家坪', '沙坪坝',
                    '江北嘴', '弹子石', '大坪', '石桥铺', '龙头寺');
                SET street_name = ELT(FLOOR(1 + RAND() * 10),
                    '解放碑', '观音桥', '南坪', '杨家坪', '沙坪坝',
                    '江北嘴', '弹子石', '大坪', '石桥铺', '龙头寺');
                    
            ELSE 
                SET city_name = '武汉';
                SET district_name = ELT(FLOOR(1 + RAND() * 7), '江岸区', '江汉区', '硚口区', '汉阳区', '武昌区', '青山区', '洪山区');
                SET community_name = ELT(FLOOR(1 + RAND() * 20),
                    '万科金色城市', '保利心语', '融侨城', '复地东湖国际', '绿地国际金融城',
                    '泛海国际', '武汉天地', '光谷坐标城', '中建光谷之星', '华侨城',
                    '江汉路', '光谷', '街道口', '中南路', '徐东',
                    '汉口', '武昌', '汉阳', '后湖', '南湖');
                SET street_name = ELT(FLOOR(1 + RAND() * 10),
                    '江汉路', '中山大道', '解放大道', '武胜路', '光谷大道',
                    '珞喻路', '中南路', '街道口', '徐东大街', '汉阳大道');
        END CASE;
        
        -- 随机房源类型和交易类型
        SET prop_type = FLOOR(RAND() * 4);
        SET trans_type = FLOOR(RAND() * 2);
        
        -- 根据房源类型设置面积和户型
        CASE prop_type
            WHEN 0 THEN  -- 住宅
                SET area_val = 60 + FLOOR(RAND() * 100);
                SET bedrooms_val = FLOOR(1 + RAND() * 4);
                SET bathrooms_val = FLOOR(1 + RAND() * 3);
            WHEN 1 THEN  -- 公寓
                SET area_val = 40 + FLOOR(RAND() * 60);
                SET bedrooms_val = FLOOR(1 + RAND() * 3);
                SET bathrooms_val = FLOOR(1 + RAND() * 2);
            WHEN 2 THEN  -- 别墅
                SET area_val = 200 + FLOOR(RAND() * 300);
                SET bedrooms_val = FLOOR(3 + RAND() * 4);
                SET bathrooms_val = FLOOR(2 + RAND() * 4);
            ELSE  -- 商铺
                SET area_val = 50 + FLOOR(RAND() * 200);
                SET bedrooms_val = 0;
                SET bathrooms_val = FLOOR(1 + RAND() * 2);
        END CASE;
        
        -- 根据交易类型和房源类型设置真实价格
        IF trans_type = 0 THEN  -- 出租
            CASE 
                WHEN city_name IN ('北京', '上海', '深圳') THEN
                    CASE prop_type
                        WHEN 0 THEN SET price_val = 4000 + FLOOR(RAND() * 8000);  -- 4000-12000
                        WHEN 1 THEN SET price_val = 3000 + FLOOR(RAND() * 5000);  -- 3000-8000
                        WHEN 2 THEN SET price_val = 15000 + FLOOR(RAND() * 25000); -- 15000-40000
                        ELSE SET price_val = 8000 + FLOOR(RAND() * 17000);  -- 8000-25000
                    END CASE;
                WHEN city_name IN ('广州', '杭州') THEN
                    CASE prop_type
                        WHEN 0 THEN SET price_val = 3000 + FLOOR(RAND() * 6000);
                        WHEN 1 THEN SET price_val = 2500 + FLOOR(RAND() * 4000);
                        WHEN 2 THEN SET price_val = 12000 + FLOOR(RAND() * 18000);
                        ELSE SET price_val = 6000 + FLOOR(RAND() * 14000);
                    END CASE;
                ELSE
                    CASE prop_type
                        WHEN 0 THEN SET price_val = 2000 + FLOOR(RAND() * 4000);
                        WHEN 1 THEN SET price_val = 1500 + FLOOR(RAND() * 3000);
                        WHEN 2 THEN SET price_val = 8000 + FLOOR(RAND() * 12000);
                        ELSE SET price_val = 4000 + FLOOR(RAND() * 10000);
                    END CASE;
            END CASE;
        ELSE  -- 出售
            CASE 
                WHEN city_name IN ('北京', '上海', '深圳') THEN
                    CASE prop_type
                        WHEN 0 THEN SET price_val = 5000000 + FLOOR(RAND() * 10000000);  -- 500-1500万
                        WHEN 1 THEN SET price_val = 3000000 + FLOOR(RAND() * 5000000);   -- 300-800万
                        WHEN 2 THEN SET price_val = 15000000 + FLOOR(RAND() * 35000000); -- 1500-5000万
                        ELSE SET price_val = 8000000 + FLOOR(RAND() * 12000000);  -- 800-2000万
                    END CASE;
                WHEN city_name IN ('广州', '杭州') THEN
                    CASE prop_type
                        WHEN 0 THEN SET price_val = 3000000 + FLOOR(RAND() * 7000000);
                        WHEN 1 THEN SET price_val = 2000000 + FLOOR(RAND() * 4000000);
                        WHEN 2 THEN SET price_val = 10000000 + FLOOR(RAND() * 20000000);
                        ELSE SET price_val = 5000000 + FLOOR(RAND() * 10000000);
                    END CASE;
                ELSE
                    CASE prop_type
                        WHEN 0 THEN SET price_val = 1500000 + FLOOR(RAND() * 3500000);
                        WHEN 1 THEN SET price_val = 1000000 + FLOOR(RAND() * 2000000);
                        WHEN 2 THEN SET price_val = 5000000 + FLOOR(RAND() * 10000000);
                        ELSE SET price_val = 3000000 + FLOOR(RAND() * 7000000);
                    END CASE;
            END CASE;
        END IF;
        
        -- 设置楼层
        SET floor_val = CONCAT(
            FLOOR(1 + RAND() * 30), '/',
            FLOOR(20 + RAND() * 30)
        );
        
        -- 设置朝向
        SET orientation_val = ELT(FLOOR(1 + RAND() * 6),
            '朝南', '朝北', '朝东', '朝西', '南北通透', '东南'
        );
        
        -- 生成标题
        SET title_val = CONCAT(
            city_name, district_name, community_name,
            CASE prop_type
                WHEN 0 THEN '精装住宅'
                WHEN 1 THEN '温馨公寓'
                WHEN 2 THEN '豪华别墅'
                ELSE '临街商铺'
            END,
            IF(bedrooms_val > 0, CONCAT(bedrooms_val, '室', bathrooms_val, '厅'), ''),
            IF(trans_type = 0, '出租', '出售')
        );
        
        -- 生成详细描述
        SET desc_val = CONCAT(
            '【房源亮点】\n',
            '1. 位置优越：', community_name, '，紧邻', street_name, '，交通便利\n',
            '2. 户型方正：', area_val, '平米，',
            IF(bedrooms_val > 0, CONCAT(bedrooms_val, '室', bathrooms_val, '卫，'), ''),
            orientation_val, '，采光充足\n',
            '3. 装修精美：精装修，家电齐全，拎包入住\n',
            '4. 配套完善：周边商场、学校、医院、地铁站等配套设施齐全\n',
            '5. 小区环境：小区绿化率高，物业管理规范，24小时安保\n\n',
            '【周边配套】\n',
            '- 交通：地铁站步行5分钟，多条公交线路\n',
            '- 商业：大型购物中心、超市、便利店\n',
            '- 教育：重点小学、中学、幼儿园\n',
            '- 医疗：三甲医院、社区医院\n',
            '- 休闲：公园、健身房、游泳馆\n\n',
            IF(trans_type = 0,
                '【租赁说明】\n- 租金：', 
                '【购房说明】\n- 总价：'),
            price_val,
            IF(trans_type = 0, '元/月\n- 付款方式：押一付三\n- 看房时间：随时看房，提前预约',
                '元\n- 产权：满五唯一\n- 看房时间：随时看房，提前预约')
        );
        
        -- 生成图片URL（使用免费图片服务）
        SET images_val = CONCAT(
            'https://images.unsplash.com/photo-1560518883-ce09059eeffa?w=800&h=600&fit=crop,',
            'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?w=800&h=600&fit=crop,',
            'https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?w=800&h=600&fit=crop,',
            'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?w=800&h=600&fit=crop,',
            'https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?w=800&h=600&fit=crop'
        );
        
        -- 插入房源
            landlord_id, title, description, price, price_type, area,
            bedrooms, bathrooms, orientation, floor, address, city, district,
            property_type, transaction_type, images, status, view_count
        ) VALUES (
            landlord,
            title_val,
            desc_val,
            price_val,
            trans_type,
            area_val,
            bedrooms_val,
            bathrooms_val,
            orientation_val,
            floor_val,
            CONCAT(city_name, district_name, street_name, FLOOR(1 + RAND() * 999), '号', community_name),
            city_name,
            district_name,
            prop_type,
            trans_type,
            images_val,
            3,  -- 已上架
            FLOOR(RAND() * 1000)
        );
        
        SET i = i + 1;
        
        IF i % 50 = 0 THEN
            COMMIT;
            SELECT CONCAT('已生成 ', i, ' 条真实感房源数据...') AS progress;
        END IF;
    END WHILE property_loop;
    
    COMMIT;
    SELECT CONCAT('✅ 真实感房源数据生成完成！共生成 ', num_properties, ' 条记录。') AS message;
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
